def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - El resto es el número como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i - 1]
            current_racha = 1

    # Verificar la última racha
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = lista[-1]

    return (max_element, max_racha)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones.

    'aaabb' se convierte en 'a3b2'.

    Si la versión comprimida es más corta que la original,
    devuelve la versión comprimida.
    Si no lo es, devuelve la original sin cambios.
    """
    if not s:
        return s

    # Contar frecuencias de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la cadena comprimida
    compressed = ""
    for char, count in counts.items():
        if count > 1:
            compressed += char + str(count)

    # Verificar si la versión comprimida es más corta
    if len(compressed) < len(s):
        return compressed
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    if not s:
        return True

    open_paren = 0
    open_bracket = 0
    open_brace = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == '[':
            open_bracket += 1
        elif char == '{':
            open_brace += 1
        elif char == ')':
            if open_paren == 0:
                return False
            open_paren -= 1
        elif char == ']':
            if open_bracket == 0:
                return False
            open_bracket -= 1
        elif char == '}':
            if open_brace == 0:
                return False
            open_brace -= 1

    return open_paren == 0 and open_bracket == 0 and open_brace == 0

def en_lotes(lista, tamano):
    """Partir una lista en sublistas de un tamaño dado. El último lote puede ser más chico."""
    if not lista:
        return []

    # Calcular cuántos lotes completos caben
    num_lotes = len(lista) // tamano

    # Calcular el tamaño del último lote (si existe)
    if len(lista) % tamano != 0:
        ultimo_tamano = len(lista) % tamano
    else:
        ultimo_tamano = 0

    # Construir las sublistas
    lotes = []
    for i in range(num_lotes):
        lotes.append(lista[i * tamano:(i + 1) * tamano])

    # Añadir el último lote si existe
    if ultimo_tamano > 0:
        lotes.append(lista[num_lotes * tamano:])

    return lotes

