def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepción, la reintenta hasta 'veces' intentos en total.
    Si todos fallan, vuelve a lanzar la última excepción.
    Devuelve el resultado si alguno funciona.

    Args:
        fn: Función que puede lanzar excepciones.
        veces: Número máximo de intentos.

    Returns:
        El resultado de la primera ejecución exitosa, o None si todos fallan.
    """
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i == veces - 1:
                raise e  # Re-raise la última excepción
            continue
    return None  # Si todos los intentos fallaron
